  <div class="custom-editor">
    <el-input v-model="currentVal" placeholder="" @change="handleValueChange"></el-input>
  </div>
</template>

<script>
const pJson = require("../../../../package.json");
export default {
  name: `${pJson.name}CustomEditor`,
  props: {
    value: {
      type: String,
      default: ""
    },
    validation: {
      type: Object,
      default: function () {
        return {};
      }
    },
    parameters: {
      type: Object,
      default: function () {
        return {};
      }
    }
  },
  data() {
    return {
      currentVal: ""
    };
  },
  watch: {
    value: {
      immediate: true,
      handler(newVal) {
        this.currentVal = newVal;
      }
    }
  },
  methods: {
    validate() {
      if (this.currentVal == "") {
        return "Mandatory";
      }
      return true;
    },
    handleValueChange() {
      let valid = this.validate();
      if (valid == true) {
        this.$emit("value-change", this.currentVal);
      } else {
        this.$emit("validate", valid);
      }
    }
  }
};
</script>
